  "case_id": "case-fintech-disruption-traditional-vs-digital-banking",
  "language": "en",
  "style": {
    "theme": "business",
    "audience": "executive",
    "tone": "authoritative, data-dense, strategic"
  },
  "goal": [
    {
      "id": "fintech-vs-traditional-crossover",
      "insight": "Visually contrast the rising trajectory of digital payment penetration and digital bank licenses against the declining trajectory of traditional bank branches, making the crossover dynamics prominent"
    },
    {
      "id": "branch-decline-acceleration",
      "insight": "Emphasize the significant pace of traditional bank branch closures, highlighting the sharp acceleration from 2019 to 2020 and the sustained high rate of closures since then"
    },
    {
      "id": "neobank-user-surge",
      "insight": "Highlight the explosive growth in neobank user counts across major markets, showing which regions lead adoption"
    },
    {
      "id": "regulatory-license-wave",
      "insight": "Show the temporal pattern of digital banking license approvals across regions, emphasizing the clustering of approvals in certain years"
    },
    {
      "id": "regional-disparity",
      "insight": "Compare the pace of fintech disruption across regions (North America, Europe, Asia-Pacific, Latin America), making geographic differences in adoption and displacement visually clear"
    }
  ]
}

